import{c as e,Q as d,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Harness 全面稽核報告 — Fable 5 判斷力外化 Session","description":"","frontmatter":{"date":"2026-07-03T00:00:00.000Z","dedup_verified":true,"domains":["harness","meta","governance"],"grounded_sources":"4 個 Sonnet 盤點 agents（skills / rules-refs / agents-hooks / memory-research）+ 主對話親測（wc -c、settings.json、branch 驗證）","source_routine":"manual-fable5-session","type":"harness-audit"},"headers":[],"relativePath":"research/reports/2026-07-03-harness-audit-fable5.md","filePath":"research/reports/2026-07-03-harness-audit-fable5.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-07-03-harness-audit-fable5.md"};function r(n,t,l,i,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="harness-全面稽核報告-—-fable-5-判斷力外化-session" tabindex="-1">Harness 全面稽核報告 — Fable 5 判斷力外化 Session <a class="header-anchor" href="#harness-全面稽核報告-—-fable-5-判斷力外化-session" aria-label="Permalink to &quot;Harness 全面稽核報告 — Fable 5 判斷力外化 Session&quot;">​</a></h1><blockquote><p>本報告是「Fable 5 唯一一次 session」的核心產出之一：診斷 + 制度檔索引 + 給未來 session 的信。 可執行計畫獨立成檔：<code>research/reports/2026-07-03-harness-upgrade-plan.md</code>。</p></blockquote><h2 id="_0-tl-dr" tabindex="-1">0. TL;DR <a class="header-anchor" href="#_0-tl-dr" aria-label="Permalink to &quot;0. TL;DR&quot;">​</a></h2><p>這套 harness 的<strong>結構品質高於預期</strong>：全部 @引用/路徑指針 0 失效、hooks 佈線零孤兒零死線、行為層硬編碼模型字串近零、agents 全用 alias。真正的風險不是「壞掉」，而是三個<strong>系統性慢性病</strong>：每-prompt 固定 token 稅、路由靠反向排除（無正向決策樹）、自報成功與版本默默過期。本次交付 4 個新制度檔（調度守則／判斷 rubric／交辦範本／維護協議）+ CLAUDE.md 重寫 + 分階段可執行計畫。</p><h2 id="_1-盤點總覽" tabindex="-1">1. 盤點總覽 <a class="header-anchor" href="#_1-盤點總覽" aria-label="Permalink to &quot;1. 盤點總覽&quot;">​</a></h2><h3 id="查到什麼-實測-2026-07-03" tabindex="-1">查到什麼（實測，2026-07-03） <a class="header-anchor" href="#查到什麼-實測-2026-07-03" aria-label="Permalink to &quot;查到什麼（實測，2026-07-03）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>實測值</th><th>方法</th></tr></thead><tbody><tr><td>Auto-load 六源</td><td><strong>18,988 bytes</strong>（門檻 19,000，剩 12B）</td><td><code>wc -c</code> 主對話親跑</td></tr><tr><td>規模</td><td>31 skills / 13 agents / 19 內容 refs（+2 索引 +1 manifest；本 PR 後內容 refs = 23）/ 21 hook scripts（佈線 10 事件、18 matcher 組）/ 7 commands</td><td>ls + agents 盤點 + 對抗審查更正</td></tr><tr><td>指針健康</td><td>@引用與路徑 <strong>0 失效</strong>；hooks 佈線<strong>無孤兒無死線</strong></td><td>test -f / test -x 逐一驗證</td></tr><tr><td>MEMORY.md</td><td>283 行 / 21,023B — <strong>超 200 行門檻</strong></td><td>wc 實測</td></tr><tr><td>settings pin</td><td><code>claude-sonnet-4-6</code>（使用者決策 #810 維持）</td><td>settings.json:4</td></tr><tr><td>本 session 模型</td><td><code>claude-fable-5</code></td><td>harness 環境宣告</td></tr><tr><td>最新可用家族</td><td><code>claude-fable-5</code> / <code>claude-opus-4-8</code> / <code>claude-sonnet-5</code> / <code>claude-haiku-4-5-20251001</code>（subagent <code>sonnet</code> alias 已於收尾實測解析至 <code>claude-sonnet-5</code>，見下方）</td><td>harness 環境宣告（非記憶）</td></tr><tr><td>Subagent model 參數</td><td>alias：<code>haiku</code> | <code>sonnet</code> | <code>opus</code> | <code>fable</code></td><td>Agent tool schema 實測</td></tr><tr><td>Effort 參數</td><td><code>low</code> | <code>medium</code> | <code>high</code> | <code>xhigh</code> | <code>max</code></td><td>Workflow/agent opts schema 實測</td></tr></tbody></table><h3 id="假設什麼" tabindex="-1">假設什麼 <a class="header-anchor" href="#假設什麼" aria-label="Permalink to &quot;假設什麼&quot;">​</a></h3><ol><li>「維持 Sonnet pin」是使用者已決策（#810），本報告不重開，只標示衍生風險（§2-3）。</li><li>CLAUDE.md 重寫在 feature branch 上進行，<strong>merge + 新 session 後才生效</strong>，不違反 mid-session 禁改規則。</li><li>evolution/ append-only 三大檔（cost-log 800K 等）屬預期 telemetry 成長，非膨脹病。</li></ol><h3 id="查不到-未確認-誠實條款" tabindex="-1">查不到／未確認（誠實條款） <a class="header-anchor" href="#查不到-未確認-誠實條款" aria-label="Permalink to &quot;查不到／未確認（誠實條款）&quot;">​</a></h3><ul><li><strong>「被導向 Opus 4.8 的請求是否消耗 Fable 額度」</strong>：文件層查不到。建議到 /usage 儀表板實測（發一個會觸發路由的請求前後對比）。</li><li><s>subagent <code>sonnet</code> alias 解析</s> → <strong>已於本 session 收尾實測解決</strong>（2026-07-03）：spawn sonnet agent 回報「The exact model ID is claude-sonnet-5」——alias 不受主對話 pin 影響，與 <code>model-selection-grid.md:25</code> 宣稱一致；<code>TODO(conflict)</code> 已解，<code>delegation-protocol.md</code> §2/§7 與 grid 已同步更新。</li><li>pilot skills 內的 benchmark 數字是否仍符合 Sonnet 5 世代：<strong>必然未重測</strong>（Sonnet 5 晚於 benchmark 建立），列入計畫 Phase 4 重校。</li></ul><h2 id="_2-a-快速診斷-—-三大慢性病-各附弱模型可照做的修法" tabindex="-1">2. A. 快速診斷 — 三大慢性病（各附弱模型可照做的修法） <a class="header-anchor" href="#_2-a-快速診斷-—-三大慢性病-各附弱模型可照做的修法" aria-label="Permalink to &quot;2. A. 快速診斷 — 三大慢性病（各附弱模型可照做的修法）&quot;">​</a></h2><h3 id="_2-1-最漏-token-每-prompt-固定稅-重複提醒-auto-load-天花板" tabindex="-1">2-1. 最漏 token：每-prompt 固定稅（重複提醒 + auto-load 天花板） <a class="header-anchor" href="#_2-1-最漏-token-每-prompt-固定稅-重複提醒-auto-load-天花板" aria-label="Permalink to &quot;2-1. 最漏 token：每-prompt 固定稅（重複提醒 + auto-load 天花板）&quot;">​</a></h3><p><strong>證據</strong>：</p><ul><li><code>user-prompt-submit.sh</code> 每個 prompt 注入 ~3 行 💡 提醒（委派優先／deep-review／MEMORY 落後），內容與 auto-load 規則<strong>重複</strong>——規則已常駐，提醒是第二次收費；且每次 spawn 3× python3 + 2× git subprocess。</li><li><code>monitor-reminder.sh</code> 每次 Bash 呼叫<strong>同步阻塞</strong> 3× python3（延遲稅，hooks 盤點確認非 async）。</li><li>Auto-load 六源 18,988B 貼死 19,000 門檻；同一判準（fan-out 上限 4、T0/T1/T2 分層）在 <code>CLAUDE.md:19-23</code>、<code>subagent-strategy.md:7-13</code>、<code>agent-team-patterns.md:36-51</code> 三處重複載入。</li><li>MEMORY.md 283 行超門檻，session 注入變肥。</li></ul><p><strong>弱模型修法</strong>（計畫 Phase 1，全部可機械驗收）：</p><ol><li><code>user-prompt-submit.sh</code> 加 per-session flag 檔：同類提醒每 session 只注入 1 次。驗收 = 同 session 第 2 個 prompt 不再出現同一 💡 行。</li><li><code>monitor-reminder.sh</code> 改 async 或合併 python3 呼叫為 1 次。驗收 = hook 執行時間對比（before/after 各跑 5 次取中位）。</li><li>委派 memory-compactor。驗收 = <code>wc -l memory/MEMORY.md</code> ≤ 120。</li><li>六源瘦身走 autoload-evolution 逐 cycle（見計畫 Phase 2，含逐段下沉表）。</li></ol><h3 id="_2-2-最易失焦-路由靠反向排除-補丁註記反模式" tabindex="-1">2-2. 最易失焦：路由靠反向排除 + 補丁註記反模式 <a class="header-anchor" href="#_2-2-最易失焦-路由靠反向排除-補丁註記反模式" aria-label="Permalink to &quot;2-2. 最易失焦：路由靠反向排除 + 補丁註記反模式&quot;">​</a></h3><p><strong>證據</strong>：</p><ul><li>31 個 skills 的路由知識分散在各 description 的「Do NOT use for」清單——弱模型要選對 skill 得先讀完所有反例，<strong>無正向決策樹</strong>。4 對高風險重疊：<code>harness-meta</code> vs <code>fable5-harness</code>（同用「四層架構」）、<code>media-research</code> vs <code>media-transcribe</code>（URL 觸發重疊）、<code>quality-pipeline</code>/<code>pilot-review</code>/<code>ship-review</code>（骨架同構）、四 pilot（description 模板複製）。</li><li><code>model-selection-grid.md</code> <strong>表格層仍列 Sonnet 4.6 為主列，靠底部長註記補丁修正</strong>——弱模型只讀表格會用到舊值。這是「補丁註記反模式」（append 修正而非改本體）的活案例。</li><li>Top 2 肥 skill（pilot-review 504 行、harness-meta 366 行）超出弱模型單次注意力有效範圍。</li></ul><p><strong>弱模型修法</strong>（計畫 Phase 3）：</p><ol><li>在 <code>trigger-index.md</code> 頂部加「正向決策樹」一頁：任務特徵 → 唯一 skill（≤25 行）。驗收 = 取 10 個歷史任務描述走樹，皆得唯一解。</li><li>立 <strong>update-in-place 規則</strong>（已寫入 <code>maintenance-protocol.md</code> §5）：修正必改 canonical 本體，禁 append 註記。</li><li><code>model-selection-grid.md</code> 表格本體重寫為 2026-07 現值，刪補丁註記。驗收 = grep 表格區無 <code>4.6</code> 主列 + 檔內無「見底部註記」字樣。</li></ol><h3 id="_2-3-最易出錯-自報成功鏈-版本默默過期" tabindex="-1">2-3. 最易出錯：自報成功鏈 + 版本默默過期 <a class="header-anchor" href="#_2-3-最易出錯-自報成功鏈-版本默默過期" aria-label="Permalink to &quot;2-3. 最易出錯：自報成功鏈 + 版本默默過期&quot;">​</a></h3><p><strong>證據</strong>：</p><ul><li><code>core.md:58</code> unverified_success 閘門單句塞 4 條件、<code>core.md:70</code> 雙重否定（「非使用者指令歧義」）——正確的規則、弱模型難 parse 的寫法。</li><li>4 個 pilot SKILL description 直寫版本號（<code>sonnet-pilot/SKILL.md:3</code> 等），Sonnet 5 已出現但 benchmark 內文未同步，<strong>且無任何機制會發現這件事</strong>。</li><li>12 個 SKILL.md 的 <code>bash scripts/xxx.sh</code> 隱含 cwd=root 假設，弱模型換 cwd 會誤判「腳本不存在」。</li></ul><p><strong>弱模型修法</strong>：</p><ol><li>unverified_success 閘門改編號 checklist——已重寫於 <code>judgment-rubrics.md</code> §2，可直接引用，未來 autoload-evolution cycle 把 core.md:58 改為指針。</li><li><code>session-init.sh</code> 已印 HARNESS_MODEL_VERSION：加 3 行比對「pin vs 環境宣告最新 alias」，不一致印 ⚠️ + 提示跑 <code>fable5-harness:calibrate</code>。驗收 = 暫改 pin 值後警示出現。</li><li>SKILL.md 命令慣例改為 <code>cd &quot;$CLAUDE_PROJECT_DIR&quot; &amp;&amp; bash scripts/...</code>（維護協議收錄；haiku 批次任務清單見計畫 Phase 3）。</li></ol><h2 id="_3-全部發現-嚴重度排序" tabindex="-1">3. 全部發現（嚴重度排序） <a class="header-anchor" href="#_3-全部發現-嚴重度排序" aria-label="Permalink to &quot;3. 全部發現（嚴重度排序）&quot;">​</a></h2><p><strong>P1（會直接造成錯誤行為）</strong></p><table tabindex="0"><thead><tr><th>#</th><th>發現</th><th>位置</th></tr></thead><tbody><tr><td>1</td><td>model-selection-grid 表格層/註記層資訊不同步（弱模型讀舊值）</td><td><code>.claude/refs/model-selection-grid.md</code></td></tr><tr><td>2</td><td>4 pilot skill 版本號硬編碼 + benchmark 默默過期、無偵測</td><td><code>{haiku,sonnet,opus,fable}-pilot/SKILL.md:3</code></td></tr><tr><td>3</td><td>unverified_success 單句 4 條件 + core.md:70 雙重否定</td><td><code>.claude/rules/core.md:58,70</code></td></tr></tbody></table><p><strong>P2（token/延遲稅、失焦風險）</strong></p><table tabindex="0"><thead><tr><th>#</th><th>發現</th><th>位置</th></tr></thead><tbody><tr><td>4</td><td>user-prompt-submit 每 prompt 重複提醒稅</td><td><code>.claude/hooks/user-prompt-submit.sh</code></td></tr><tr><td>5</td><td>monitor-reminder 同步阻塞每次 Bash</td><td><code>.claude/hooks/monitor-reminder.sh</code></td></tr><tr><td>6</td><td>T0/T1/T2 + fan-out 判準三檔重複</td><td>CLAUDE.md / subagent-strategy.md / agent-team-patterns.md</td></tr><tr><td>7</td><td>MEMORY.md 283 行超門檻</td><td><code>memory/MEMORY.md</code></td></tr><tr><td>8</td><td>4 對 skill trigger 重疊、無正向決策樹</td><td>見 §2-2</td></tr><tr><td>9</td><td>pilot-review 504 行 / harness-meta 366 行注意力衰減</td><td><code>.claude/skills/{pilot-review,harness-meta}/SKILL.md</code></td></tr></tbody></table><p><strong>P3（小修）</strong></p><table tabindex="0"><thead><tr><th>#</th><th>發現</th><th>位置</th></tr></thead><tbody><tr><td>10</td><td>hooks matcher 群組計數失準：README=18 <strong>正確</strong>；過期的是 <code>scripts/healthcheck.sh:725</code> baseline=17（初版盤點誤判 17，經對抗審查實測 PostToolUse=6 組、總計 18 更正）</td><td><code>scripts/healthcheck.sh:725</code></td></tr><tr><td>11</td><td>memory-pr-record-gh.sh matcher 全量 Bash 過寬</td><td>settings.json PostToolUse</td></tr><tr><td>12</td><td>12 個 SKILL.md 隱含 cwd 假設</td><td>清單：<code>research/reports/2026-07-03-harness-audit-appendix/inv-skills.md</code> §4</td></tr><tr><td>13</td><td>fable5-harness 缺 METADATA.json/GOTCHAS.md（可能刻意薄入口，需確認意圖）</td><td><code>.claude/skills/fable5-harness/</code></td></tr><tr><td>14</td><td>pilot-review D1-D3 審查 prompt 用「合理/清晰」無錨定</td><td><code>pilot-review/SKILL.md:150,183,221</code></td></tr></tbody></table><h2 id="_4-交付物索引" tabindex="-1">4. 交付物索引 <a class="header-anchor" href="#_4-交付物索引" aria-label="Permalink to &quot;4. 交付物索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>交付</th><th>路徑</th><th>作者</th></tr></thead><tbody><tr><td>A 快速診斷</td><td>本檔 §2</td><td>Fable 5 親寫</td></tr><tr><td>B CLAUDE.md 重寫</td><td><code>CLAUDE.md</code>（備份 <code>.claude/backups/CLAUDE.md.20260703.bak</code>）</td><td>Fable 5 親寫</td></tr><tr><td>C 模型調度守則</td><td><code>.claude/refs/delegation-protocol.md</code></td><td>Fable 5 親寫</td></tr><tr><td>D 判斷力外化</td><td><code>.claude/refs/judgment-rubrics.md</code></td><td>Fable 5 親寫</td></tr><tr><td>E 交辦範本</td><td><code>.claude/refs/task-templates.md</code></td><td>Sonnet 起草 + Fable 審</td></tr><tr><td>F 維護協議</td><td><code>.claude/refs/maintenance-protocol.md</code></td><td>Sonnet 起草 + Fable 審</td></tr><tr><td>可執行計畫</td><td><code>research/reports/2026-07-03-harness-upgrade-plan.md</code></td><td>Fable 5 親寫</td></tr><tr><td>G 給未來 session 的信</td><td>本檔 §5</td><td>Fable 5 親寫</td></tr></tbody></table><h2 id="_5-g-給未來-session-的信" tabindex="-1">5. G. 給未來 session 的信 <a class="header-anchor" href="#_5-g-給未來-session-的信" aria-label="Permalink to &quot;5. G. 給未來 session 的信&quot;">​</a></h2><p>寫給之後接手的每一個 Sonnet／Haiku／Opus session——你們不缺能力，缺的是我這次有空間慢慢看全局。以下是看完全局後的三句話。</p><h3 id="三件沒被問到、但最重要的事" tabindex="-1">三件沒被問到、但最重要的事 <a class="header-anchor" href="#三件沒被問到、但最重要的事" aria-label="Permalink to &quot;三件沒被問到、但最重要的事&quot;">​</a></h3><ol><li><strong>最大風險不是規則寫錯，是規則慢性失真。</strong> model-selection-grid 的「表格留舊值、底部註記寫新值」已是活案例：正確資訊存在，但放在你不會讀到的位置。這次立的最重要制度不是任何新規則，是 <code>maintenance-protocol.md</code> §4 的 <strong>update-in-place</strong>——它決定其他所有規則會不會爛掉。修正資訊時改本體，永遠。</li><li><strong>每回合的小稅比一次性大開銷更貴，而且沒人質疑它。</strong> user-prompt-submit 每個 prompt 注入與 auto-load 重複的提醒、monitor-reminder 每次 Bash 同步阻塞——單次不痛，長 session 累積遠超一次大讀取。新增任何 hook／常駐注入前，先量測（計畫 1.2/1.3 的驗收寫法就是範本），並回答「auto-load 是不是已經說過這件事」。</li><li><strong>「現在到底跑哪個模型」沒有單一事實源。</strong> settings pin、subagent alias、pilot benchmark、model-selection-grid 四處各自演化。從今天起 <code>delegation-protocol.md</code> §2 是 canonical 檔位表：更新只改那裡，其他地方指過去。查證不到的值標「未確認」，寧可空著也不要憑記憶填——這份稽核發現行為層硬編碼近零，是這套 harness 最值得守住的資產。</li></ol><h3 id="這套制度最可能的退化方式-與預防" tabindex="-1">這套制度最可能的退化方式（與預防） <a class="header-anchor" href="#這套制度最可能的退化方式-與預防" aria-label="Permalink to &quot;這套制度最可能的退化方式（與預防）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>退化方式</th><th>預防</th></tr></thead><tbody><tr><td>規則只增不刪，六源爬回 19,000B</td><td>每次 autoload-evolution cycle 先跑 <code>wc -c</code> 六源量測（或 <code>scripts/measure.sh</code>），超線即拒收該 cycle</td></tr><tr><td>rubrics 被當散文掃過，不當 gate 走</td><td>保持編號 checklist 形態；交辦時引用具體條號（「依 R2 驗收」而非「好好驗收」）</td></tr><tr><td>對抗審查／read-back 在趕時間時被跳過</td><td>R2 第 2 條已把 fresh-context 驗證寫成「完成」的必要條件——跳過就不能宣告完成，語氣可調資訊不省</td></tr><tr><td>制度檔自己變 decaying cache</td><td>14–30 天重審在 maintenance-protocol §5，但需要觸發器：建議掛 <code>/schedule</code> routine，別靠人記得</td></tr></tbody></table><h3 id="誠實條款-信心最低的產出" tabindex="-1">誠實條款：信心最低的產出 <a class="header-anchor" href="#誠實條款-信心最低的產出" aria-label="Permalink to &quot;誠實條款：信心最低的產出&quot;">​</a></h3><ol><li><strong>計畫 Phase 2 的 byte 節省估算</strong>——來自單次 Sonnet 盤點推估，未經 eval；以每 cycle 實測為準。</li><li><strong>task-templates.md 與 maintenance-protocol.md</strong>——Sonnet 起草、我逐行審過並修了 2 處，但範本的實戰有效性只有用過才知道；用出問題就改，別供著。</li><li><strong>三個 review-pipeline skill（quality-pipeline/pilot-review/ship-review）的合併建議</strong>——我沒挖使用數據，三者可能各有存在理由；計畫 3.6 要求先統計再決策，不要直接信我的「骨架同構」判斷。</li><li><strong>未確認事實</strong>：sonnet alias 已於收尾實測解決（→ <code>claude-sonnet-5</code>）；剩 <strong>Opus 4.8 導流額度</strong>一項——標在 delegation-protocol §7 並附實測方法，實測前引用其推論不可靠。</li></ol><p>拆解、驗證、多樣本評審補得了執行品質；模糊題與品味判斷補不了——遇到就升級或問人，明說做不到不丟臉，靜默硬做才是。</p>',45)])])}const u=e(s,[["render",r]]);export{p as __pageData,u as default};
